ProjectALife.DialogueShards["scenes_misc_6"] = {
{"fw_ld4_topics_b_0024","outpost_fire",2,"reg=civilian,family,worker,rescue",{1,"Pass the marshmallows",2,"We don't have marshmallows",1,"I know, I'm pretending",2,"Then pass me the pretend graham crackers"}},
{"fw_ld4_topics_b_0025","outpost_fire",2,"reg=civilian,family,worker,rescue",{1,"Tell us a ghost story",2,"We're living in one",1,"A different one",2,"Okay, once there was a kid who never said goodnight to his mother, and the house remembered"}},
{"fw_ld4_topics_b_0026","outpost_fire",2,"reg=civilian,family,worker,rescue",{1,"Don't stare at the fire",2,"Why?",1,"You'll ruin your night vision",2,"What night vision? I can't even see my own hand",1,"Exactly"}},
{"fw_ld4_topics_b_0027","outpost_fire",2,"reg=civilian,family,worker,rescue",{1,"It's nice to be warm",2,"Yeah",1,"For a second I forgot to be afraid",2,"Don't remind me, now I remember"}},
{"fw_ld4_topics_b_0028","outpost_fire",2,"reg=civilian,family,worker,rescue",{1,"Anyone know a song?",2,"I know one",1,"Sing it",2,"I only know the chorus",1,"Then sing the chorus ten times"}},
{"fw_ld4_topics_b_0029","outpost_fire",2,"reg=civilian,family,worker,rescue",{1,"My grandfather used to sit by the fire and whittle",2,"What did he make?",1,"Whistles, mostly",2,"Did they work?",1,"Terribly, but we loved them"}},
{"fw_ld4_topics_b_0030","outpost_fire",2,"reg=law,swat",{1,"Feet up, boots off",2,"You sure?",1,"Five minutes, then back on",2,"Best five minutes of the day"}},
{"fw_ld4_topics_b_0031","outpost_fire",2,"reg=military,elite",{1,"I miss somebody saying coffee's ready",2,"Real coffee?",1,"Real enough",2,"I'd take that lie just to have the morning back"}},
{"s10_fire_ferris_wheel_story_001","outpost_fire",3,"reg=civilian,family,worker|day=10,300|hour=19,1|mood=warm",{1,"Your turn for a story",2,"I told one Tuesday",1,"You told the carnival one, that's the only story you own",2,"Then I'll tell it with a different ending",3,"Does the Ferris wheel still stop at the top?",2,"It always stops at the top - always has, that's the story"}},
{"s10_fire_cow_from_indiana_002","outpost_fire",2,"reg=military|tmp=seasoned,veteran|hour=18,23|mood=funny",{1,"Who built that bonfire?",2,"It's a cooking fire, Sergeant",1,"You could cook a whole cow on it from Indiana - pull half those logs - now"}},
{"s10_fire_church_bus_story_003","outpost_fire",3,"reg=raider,prison|tmp=predator,seasoned|hour=19,2|mood=grim",{1,"Tell the one about the church bus",2,"That ain't a story, I was there",3,"That's what makes it good",2,"No, that's what makes it true - different thing"}},
{"s10_fire_two_thirds_smores_004","outpost_fire",3,"reg=family|day=5,200|hour=18,22|mood=warm",{1,"Found graham crackers in the Hendersons' pantry, and a bag of marshmallows gone hard as rocks",2,"Hard ones melt the same",3,"No chocolate, though",1,"So it's two-thirds of the best thing in the world - the kids won't do the math"}},
{"s10_fire_barrel_looking_005","outpost_fire",3,"reg=gang|hour=19,3|mood=calm",{1,"Fire in a barrel under the overpass, like winter back home",2,"It's ninety degrees - why do we got a fire?",1,"Mosquitoes, and I like looking at it",3,"He likes looking at it",1,"Y'all got something better to look at out here?"}},
{"s10_fire_leaning_pump_006","outpost_fire",3,"reg=club|hour=19,2|mood=funny|world=rain",{1,"Remember the ride out to South Dakota in eighty-six? Rain for three whole states",2,"You dropped your bike at a gas station in Nebraska and blamed the pump",1,"The pump was leaning",3,"Tell it right or don't tell it",1,"The pump was leaning a little"}},
{"s10_fire_too_many_stars_007","outpost_fire",2,"reg=prison|hour=21,4|mood=warm",{1,"Eleven years I never saw one star, yard lights washed 'em all out",2,"Well, look up, then",1,"I am, there's too many - somebody ought to switch a few off"}},
{"s10_fire_aisle_seven_008","outpost_fire",3,"reg=law|hour=19,1|mood=funny",{1,"Worst call you ever took, before all this",2,"Heifer loose in the grocery store in Radcliff",3,"That's not so bad",2,"Aisle seven - pickles, glass jars, floor to ceiling"}},
{"s10_fire_cold_chili_mac_009","outpost_fire",3,"reg=elite|tmp=veteran|hour=18,23|mood=funny",{1,"No fire tonight",2,"Heat tab?",1,"Not even a heat tab - eat it cold",3,"Cold chili mac is a war crime",1,"Write it up, I'll forward it"}},
{"s10_fire_homecoming_bonfire_010","outpost_fire",2,"reg=civilian,family|role=family_youth,civilian_woman,civilian_man|tmp=fresh|hour=19,1|mood=sad",{1,"Last bonfire I sat at was homecoming - Tyler Mason tried to kiss me behind the bleachers",2,"Did he get to?",1,"He tried, I let him try - heh, he was so bad at it, he kept, he",1,"Anyway, pass me that stick"}},
{"s10_fire_the_chip_011","outpost_fire",3,"reg=worker,civilian|tmp=seasoned|hour=19,1|mood=warm",{1,"Bottle's going around",2,"Pass me by",3,"Since when?",2,"Four years this October - Chip's right here in my wallet",1,"World ended, Ray",2,"Didn't end for the chip"}},
{"s10_fire_built_wrong_012","outpost_fire",2,"reg=rescue|role=rescue_firefighter|hour=18,23|mood=funny",{1,"That fire's built wrong, there's no air getting under it",2,"You put fires out for twenty years, you don't get to be the expert on starting 'em",1,"Who do you think found out how every one of 'em started?"}},
{"s10_fire_water_went_down_013","outpost_fire",2,"reg=family,civilian|role=family_elder|hour=18,23|mood=grim",{1,"Y'all think this is bad - Mama rowed us out of Louisville in thirty-seven, water up to the second floor",2,"Was it worse than this?",1,"No, the water went back down"}},
{"s10_fire_behind_irvington_014","outpost_fire",3,"reg=raider|tmp=predator|hour=19,3|mood=funny",{1,"Tell 'em what that fella said when you took his truck",2,"Said God would judge me",3,"And what'd you say?",2,"Said God better get in line behind the Irvington boys - they got first dibs",1,"Hahaha! First dibs!"}},
{"s10_fire_two_eleven_frames_015","outpost_fire",3,"reg=military|hour=19,1|mood=warm",{1,"What were you doing the Thursday night before?",2,"Laundry, folded it all real neat, too - never did put it away",3,"Bowling league in Radcliff - Bowled a two-eleven, best game of my life",1,"Want to tell it?",3,"Frame by frame?",1,"We got all night, Specialist"}},
{"s10_fire_green_wood_smoke_016","outpost_fire",2,"reg=civilian,outlaw,family|tmp=seasoned,veteran|day=10,300|mood=calm",{1,"I'd rather not build up a smoky fire if we don't need one",2,"Even if it means eating cold again?",1,"Then we eat cold beans and I have one less thing to worry about. I'll take that trade for now"}},
{"s10_fire_mason_jar_ride_017","outpost_fire",2,"reg=outlaw|hour=19,2|mood=funny",{1,"Daddy ran liquor down the Brandenburg road with his headlights off - knew every curve by the fence posts",2,"You ever ride along?",1,"Once, I was nine - threw up in a mason jar",2,"What'd your daddy do?",1,"Made me keep the jar, said a man cleans up his own cargo"}},
{"s10_fire_cricket_band_018","outpost_fire",2,"reg=family,civilian|hour=20,1|mood=warm",{1,"Dance with me",2,"There's no music",1,"There's crickets, crickets keep better time than that band at our wedding",2,"That drummer was drunk by the cake",1,"So you remember - come here"}},
{"s10_fire_pine_christmas_019","outpost_fire",2,"reg=gang,crime|hour=19,3|mood=sad",{1,"Smell that? Pine, smells like my aunt's apartment at Christmas",2,"Your aunt was all right",1,"She was all right, she was on the bus on Dixie that Friday",1,"Anyway, pass the can over here"}},
{"s10_fire_chapter_twelve_020","outpost_fire",1,"reg=civilian,worker,family|hour=19,1|mood=funny",{1,"Chapter eleven's going in the fire",1,"Never will find out if it was the nephew",1,"Heh - chapter twelve - let the smoke wonder about it"}},
{"s10_fire_columbus_day_021","outpost_fire",3,"reg=military,civilian|tmp=seasoned,veteran|day=90,110|hour=18,23|mood=funny",{1,"First night this fire's for warm instead of for cooking",2,"October already?",1,"Fella on the CB says it's the twelfth, so I'm calling it the twelfth",3,"Columbus Day",2,"He'd have taken one look at this county and turned the boats around"}},
{"s10_fire_boots_dry_forever_022","outpost_fire",2,"reg=worker,civilian,military,club|hour=19,3|mood=funny",{1,"Something's burning that ain't wood",2,"My boots",1,"You set your boots that close?",2,"Wanted 'em dry by morning - well, they'll be dry for good now"}},
{"fw_ld4_topics_b_0016","outpost_guard",2,"reg=civilian,family,worker,rescue",{1,"What would you do if a woman carrying a baby asked to come in?",2,"Ask whether either of them was hurt, without crowding her",1,"Hard to show you much with both arms full",2,"Then ask how she wants to handle it. You don't just grab somebody's baby",1,"I'd be scared of dropping her",2,"That's something you say before you offer to hold her"}},
{"fw_ld4_topics_b_0017","outpost_guard",2,"reg=civilian,family,worker,rescue|hour=16,5",{1,"How many of us on the wall tonight?",2,"Four",1,"That's not enough",2,"It's what we've got",1,"Then we pray they're lazy tonight"}},
{"fw_ld4_topics_b_0018","outpost_guard",2,"reg=civilian,family,worker,rescue",{1,"Somebody's coming up the road",2,"How many?",1,"Three, walking slow",2,"Armed?",1,"Not that I can see",2,"Fire a shot into the air, see how they react"}},
{"fw_ld4_topics_b_0019","outpost_guard",2,"reg=civilian,family,worker,rescue",{1,"Nobody opens that gate unless I say so, got it?",2,"Okay",1,"Rule number two, don't make me repeat rule number one",2,"Got it"}},
{"fw_ld4_topics_b_0020","outpost_guard",2,"reg=civilian,family,worker,rescue",{1,"I hate guard duty",2,"Why?",1,"It's all waiting and no payoff",2,"Waiting IS the payoff, nothing happened, that's a win"}},
{"fw_ld4_topics_b_0021","outpost_guard",2,"reg=law,swat",{1,"Who goes there?",2,"Friendly",1,"Friendly who?",2,"Friendly Frank, from the north road",1,"Advance and be recognized, Frank"}},
{"fw_ld4_topics_b_0022","outpost_guard",2,"reg=law,swat|hour=20,5",{1,"Rotation's at midnight",2,"Who's up?",1,"Reyes and Collins",2,"Collins snores",1,"Collins is good with a rifle, tolerate the snoring"}},
{"fw_ld4_topics_b_0023","outpost_guard",2,"reg=military,elite",{1,"Halt, identify yourself",2,"Sergeant Hill, Alpha company",1,"Password?",2,"Bluegrass",1,"Welcome back, Sergeant"}},
{"s10_guard_dentist_gate_023","outpost_guard",3,"reg=civilian,worker|tmp=seasoned|day=8,300|mood=funny",{1,"Fella at the gate says he's a dentist",2,"Can he prove it?",1,"Looked at you from forty feet off and said you grind your teeth at night",2,"Well, I do grind at night",3,"Let the man in"}},
{"s10_guard_white_shirt_stick_024","outpost_guard",3,"reg=military|tmp=seasoned,veteran|day=3,200|mood=grim",{1,"White shirt on a stick, eleven o'clock, by the silo",2,"Could be a trick",1,"Could be, could be a man who owns one white shirt",3,"Signal him in slow - hands on his head, walking the ditch line",2,"And if he comes in fast?",3,"Then he wasn't really asking"}},
{"s10_guard_crow_roof_025","outpost_guard",2,"reg=raider|tmp=predator|mood=funny",{1,"Four hours on this roof and the only thing I shot was a crow",2,"Boss said no shooting",1,"The crow was looking at me",2,"Well, now everything for a mile is looking at you - enjoy"}},
{"s10_guard_lawnmower_report_026","outpost_guard",2,"reg=law|day=10,300|mood=warm",{1,"Lady at the barricade wants to report her riding mower stolen",2,"You take the report?",1,"Took it, wrote it on the back of a feed store receipt - serial number and all",2,"Good, folks need to see somebody still writes things down"}},
{"s10_guard_whistle_rules_027","outpost_guard",2,"reg=family|day=10,300|mood=warm",{1,"Two blows on the whistle if it's one of them - three if it's people",2,"What if it's a dog?",1,"No blows, we like dogs",2,"What if it's a dog and one of them?",1,"Then two blows, and we'll worry about the dog after"}},
{"s10_guard_same_walk_028","outpost_guard",2,"reg=prison|day=10,300|mood=funny",{1,"Six years I watched hacks walk the fence, now look at me up here",2,"You look good - real natural",1,"Don't say that, I ain't one of them",2,"You do the exact same walk, man - slow at the corner, look back over your shoulder",1,"I'm looking back 'cause something's out there",2,"That's what they said too"}},
{"s10_guard_range_card_029","outpost_guard",2,"reg=elite|tmp=veteran|mood=calm",{1,"Range card for this post",2,"Mailbox, eighty, blue car, one-forty - church steeple, three hundred",1,"Steeple's two-sixty, I paced it",2,"You paced three hundred meters of open road?",1,"Two-sixty"}},
{"s10_guard_shrink_wrap_030","outpost_guard",3,"reg=worker|day=5,300|mood=grim",{1,"Wall held last night, pallets and shrink wrap",2,"Shrink wrap, we're holding off the end of the world with shrink wrap",1,"Two hundred turns around every stack, you try pushing through that",3,"One got tangled in it like a fly in a web - still in there by the loading dock",2,"Still in there doing what?",3,"Chewing on the plastic - go look if you want"}},
{"s10_guard_deer_stand_sentence_031","outpost_guard",2,"reg=civilian,family|tmp=fresh,seasoned|hour=11,17|mood=funny|world=rain,hot",{1,"Swap me out, I can't see straight, it's so hot",2,"You've been up there forty minutes",1,"Forty minutes in a tin deer stand in this heat, that's time served right there",2,"Come down and dunk your head in the rain barrel - the green one, not the drinking one"}},
{"s10_guard_wake_martinez_032","outpost_guard",3,"reg=military|day=5,200|mood=calm",{1,"She won't lift her shirt for you, Private - would you?",2,"It's the procedure, Specialist, everybody gets checked",3,"Go get Martinez - Martinez checks the women",1,"Martinez is asleep",3,"Then wake her up, that's also procedure"}},
{"s10_guard_two_stroke_033","outpost_guard",3,"reg=club|mood=calm|world=summer",{1,"Single headlight coming up the road",2,"Bike, or a car with one burnt out?",1,"Listen at it, that's a two-stroke, some kid on a dirt bike",3,"Kid on a dirt bike riding straight up to our gate - that's brave or stupid",2,"Same thing this summer"}},
{"s10_guard_mrs_pryor_rifle_034","outpost_guard",2,"reg=gang|mood=funny",{1,"Roof's the best spot, I can see clear to the overpass",2,"And anybody with a rifle can see you",1,"Nobody on this block's got a rifle but us",2,"Mrs. Pryor on three has her husband's deer rifle, and she hates you",1,"She hates everybody",2,"She hates you specific, you parked on her roses in May"}},
{"s10_guard_three_rounds_035","outpost_guard",2,"reg=civilian,worker,family|tmp=seasoned|day=15,300|mood=grim",{1,"How many rounds you got up there?",2,"Three rounds",1,"Three? That's all?",2,"Three, and a rifle that looks like it's got thirty - most of this job is standing where folks can see the rifle"}},
{"s10_guard_vehicle_code_wedding_036","outpost_guard",3,"reg=law|day=10,300|mood=funny",{1,"Couple at the barricade asking can I marry 'em",2,"Troopers can't marry anybody",1,"I told 'em, they said nobody's checking anymore",3,"So do it - read 'em something out of the vehicle code, they won't know the difference",1,"I'm not marrying two people out of the vehicle code",2,"Why not? There's a whole section on yielding"}},
{"s10_guard_dobbs_watch_037","outpost_guard",2,"reg=military,law,civilian|tmp=seasoned,veteran|day=8,200|mood=grim",{1,"Third one from the left, by the culvert - that's Dobbs",2,"Dobbs went out on the water run Thursday",1,"He's still wearing my watch, I loaned it to him for the run",2,"You want it back?",1,"I want him to quit walking at the gate"}},
{"s10_guard_brooms_with_hats_038","outpost_guard",3,"reg=raider|tmp=predator,seasoned|mood=funny",{1,"Green pickup went by slow - twice now, same two in the cab",2,"Irvington boys",1,"Counting our windows",3,"Let 'em count, put a rifle in every window - Brooms if we run short",2,"Brooms?",3,"Put a hat on a broom, from the road that's a man who don't blink"}},
{"s10_guard_blue_rag_039","outpost_guard",2,"reg=civilian,family|day=15,300|mood=funny",{1,"Red rag on the wall means come in, white rag means all clear in the field",2,"What's the blue rag mean?",1,"Blue rag is Martha's good dish towel, and she wants it back by supper"}},
{"s10_guard_safety_left_on_040","outpost_guard",2,"reg=elite|tmp=veteran|day=5,300|mood=calm|world=stairs",{1,"Civilian on the north wall is asleep again",2,"Same one?",1,"Same one, took his rifle down the ladder and back up - he never stirred",2,"You wake him?",1,"Left the bolt open and a note in the chamber - he'll work it out"}},
{"s10_guard_rabbit_news_041","outpost_guard",1,"reg=family|sex=f|day=10,300|hour=7,19|mood=warm",{1,"Shh - Shh, mama's watching the road",1,"Nothing on the road, baby, nothing, and more nothing, and a rabbit",1,"Rabbit's the best news all day, wave bye to the rabbit"}},
{"s10_guard_pillowcase_sandbags_042","outpost_guard",3,"reg=military|day=20,300|mood=funny",{1,"Sandbags on the east side are rotting through - Sand's running out of 'em like an hourglass",2,"We got more bags?",1,"Pillowcases, forty of 'em from the motel on 31W",3,"Floral print, that'll put the fear of God in them",1,"Fill 'em and quit decorating"}},
{"s10_guard_whippoorwill_043","outpost_guard",3,"reg=outlaw|mood=funny",{1,"Anybody comes up the holler, you whistle like a whippoorwill",2,"I can't whistle like a whippoorwill",1,"Then whistle like a boy who can't, nobody out there knows the difference",3,"The revenuers always knew",1,"Revenuers are dead, Clyde, every last one",3,"Then I'll whistle however I want"}},
{"s10_guard_bell_rope_044","outpost_guard",2,"reg=civilian,family,rescue|tmp=seasoned,veteran|day=10,300|mood=grim",{1,"Bell rings once, everybody inside, twice, everybody to the wall",2,"And if it keeps on ringing?",1,"Then whoever's on the rope can't stop pulling, you go to the wall and find out why"}},
{"s10_mech_cereal_box_gasket_023","outpost_mechanic",3,"reg=worker,civilian|day=10,300|mood=funny",{1,"Cut a new gasket for the water pump out of a cereal box",2,"That'll never hold",1,"Held on my brother's truck in seventy-nine - clear to Nashville and back",3,"And after Nashville?",1,"He sold it, after Nashville was the other fella's problem"}},
{"s10_mech_mail_truck_lugs_024","outpost_mechanic",2,"reg=military|tmp=seasoned,veteran|day=5,300|mood=calm",{1,"Front left's got a nail in it",2,"Plug kit's empty",1,"Then pull the tire off that mail truck by the fence - Mail's not running",2,"Mail truck's a different bolt pattern",1,"Then walk the lot with a tape measure till something matches"}},
{"s10_mech_stale_gas_carb_025","outpost_mechanic",3,"reg=club|mood=funny|world=water,storm",{1,"Carb's gummed solid, gas went bad",2,"Gas don't go bad in a month",1,"This came out of a lawnmower can that's been in a shed since nineteen ninety",3,"Splash some of that white lightning in there - burns hot",1,"Put moonshine in my bike and I'll put you in the creek"}},
{"s10_mech_air_cleaner_026","outpost_mechanic",2,"reg=civilian,family|tmp=fresh|day=5,120|mood=funny",{1,"Manual says remove the air cleaner assembly - what's an air cleaner assembly?",2,"The big round lid",1,"On top?",2,"Honey, it's the only thing on top"}},
{"s10_mech_arlis_wrench_027","outpost_mechanic",2,"reg=worker,civilian|tmp=seasoned|day=10,300|mood=sad",{1,"Whose torque wrench? There's a name burned in the handle",2,"Arlis, he sent that thing off to be checked every spring like it was a family Bible",1,"It reads five pounds light",2,"Don't tell him, I mean, just go by feel"}},
{"s10_mech_resistor_key_028","outpost_mechanic",3,"reg=gang,crime|mood=funny",{1,"Who here can start a car with no key?",2,"Everybody here, man",3,"Not the newer ones, newer ones got that little chip thing in the key",1,"Then we drive old cars, old cars are the future now",2,"My uncle's rusty seventy-one sedan finally gets some respect"}},
{"s10_mech_nothing_glows_029","outpost_mechanic",3,"reg=elite|tmp=veteran|mood=calm",{1,"Pull the brake light bulbs",2,"Dome light too?",1,"Dome, reverse, the little one in the glovebox, nothing on this truck glows",3,"Horn?",1,"Cut the wire"}},
{"s10_mech_steel_box_bus_030","outpost_mechanic",3,"reg=raider|tmp=predator,seasoned|mood=funny",{1,"Plate's welded on the bus windshield - cut a slot to see through",2,"You cut the slot at your eye level",1,"What's wrong with that?",2,"You're six foot four, nobody else can see a thing but sky",3,"Then he drives",1,"I don't want to drive a steel box with no windows",3,"Nobody does, that's what makes it safe"}},
{"s10_mech_light_bar_trunk_031","outpost_mechanic",2,"reg=law|day=5,200|mood=sad",{1,"Take the light bar off the cruiser",2,"That's county property",1,"County's a line on a map right now, and that chrome catches the sun a mile off",2,"It goes in the trunk, then, when this is over I'm bolting it back on"}},
{"s10_mech_hay_bale_muffler_032","outpost_mechanic",3,"reg=worker,civilian,family|tmp=seasoned|day=10,300|mood=calm",{1,"Stack hay bales around the generator - three high",2,"It'll catch",1,"Leave a gap up top for the heat, hay eats noise",3,"Hay eats sparks too, I watched the Beasley barn go up in seventy-four",1,"Then you sit next to it with the extinguisher, congratulations, you're fire watch"}},
{"s10_mech_vocational_welder_033","outpost_mechanic",2,"reg=prison|mood=funny",{1,"Where'd you learn to weld like that?",2,"State vocational program - eighteen months, got a certificate and everything",1,"Taxpayers finally got their money's worth",2,"Taxpayers are mostly dead now, but I like to think they'd be proud"}},
{"s10_mech_short_minute_pump_034","outpost_mechanic",2,"reg=rescue|role=rescue_firefighter|day=10,300|mood=funny|world=water",{1,"Engine pump will pull straight out of the creek if we can get the hard suction down that bank",2,"A thousand gallons a minute, to fill a cistern that holds four hundred",1,"So it'll be a real short minute",2,"Somebody stand by the cistern with a flag, and a raincoat"}},
{"s10_mech_deke_bike_cover_035","outpost_mechanic",2,"reg=club|day=8,300|mood=sad",{1,"Want me to pull parts off Deke's bike?",2,"No, leave it be",1,"Carb off his would fit yours perfect",2,"I said no - put the cover back on it - Tuck the corners"}},
{"s10_mech_my_daddy_knew_036","outpost_mechanic",3,"reg=family|tmp=fresh|day=5,90|mood=sad",{1,"Daddy, is the truck fixed?",2,"Not yet, bug",3,"Go help your mama with the wash, your daddy's thinking",2,"My daddy could tear one of these down blindfolded, I held the flashlight - thirty years, I held the flashlight"}},
{"s10_mech_six_batteries_037","outpost_mechanic",2,"reg=worker,rescue,civilian|tmp=seasoned|day=15,300|mood=calm",{1,"Six car batteries on a board gets the clinic two hours of light",2,"Two hours and then?",1,"Then somebody idles the truck an hour to charge one back up - want to guess who?",2,"I'll bring a book"}},
{"s10_mech_not_wasting_sugar_038","outpost_mechanic",3,"reg=raider|tmp=predator|mood=funny",{1,"Sugar in the Irvington crew's gas tanks, two pounds a truck",2,"Sugar's worth more than their trucks",1,"Salt, then",3,"Salt don't do a thing to a gas tank",1,"Then sand, damn it, I'm not pouring good sugar in those boys' trucks"}},
{"s10_mech_righty_loosey_039","outpost_mechanic",2,"reg=military|role=soldier_nco,soldier_green,soldier|mood=funny",{1,"Which way loosens, Sergeant?",2,"Lefty loosey, Private",1,"I'm on my back under here, it's upside down",2,"Then it's righty loosey, welcome to motor pool"}},
{"s10_mech_toothbrush_plugs_040","outpost_mechanic",1,"reg=worker,civilian,club,outlaw|mood=funny",{1,"Come on, come on, sweetheart - turn over for me",1,"New fuel filter, cleaned every plug with my own toothbrush",1,"Don't you do me like this with everybody watching"}},
{"s10_mech_station_wagon_radiator_041","outpost_mechanic",2,"reg=civilian,worker,military,law|tmp=seasoned|day=10,300|mood=grim",{1,"Station wagon's got a good radiator - pull it",2,"There's a car seat still buckled in the back",1,"Leave the car seat, pull the radiator",2,"I know, I'm doing it"}},
{"s10_mech_forty_minute_cutlass_042","outpost_mechanic",2,"reg=crime|mood=funny",{1,"I used to strip a two-door down to the frame in forty minutes flat",2,"Then why's this one taken you all day?",1,"Because now I got to put it back together, nobody ever paid me for that part"}},
{"s10_mech_tractor_crank_043","outpost_mechanic",3,"reg=civilian,family,worker|tmp=seasoned|day=15,300|mood=calm",{1,"That tractor's older than the two of us put together",2,"That's why it runs, no wires you can't see, nothing fancy to fail",3,"It failed twice this week",2,"And I fixed it twice with a coat hanger - try that on a new one"}},
{"s10_mech_radio_off_the_car_044","outpost_mechanic",2,"reg=military,law|tmp=seasoned,veteran|day=5,300|mood=calm",{1,"Base set's dead - can we run it off the truck?",2,"Twelve volts - Alligator clips on the battery, and don't cross the leads",1,"What happens if I cross the leads?",2,"Then we learn what burnt radio smells like and we go back to shouting"}},
{"fw_ld4_topics_b_0037","outpost_medic",2,"reg=civilian,family,worker,rescue",{1,"Hold this",2,"What is it?",1,"His arm",2,"His whole arm?",1,"His whole arm, hold it still while I wrap it"}},
{"fw_ld4_topics_b_0038","outpost_medic",2,"reg=civilian,family,worker,rescue",{1,"Are you the doctor?",2,"I'm the closest thing",1,"What were you before?",2,"A pharmacy tech, but I read a lot"}},
{"fw_ld4_topics_b_0039","outpost_medic",2,"reg=civilian,family,worker,rescue",{1,"How's the fever?",2,"Dropping",1,"Thank God",2,"Don't thank Him yet, it could spike again"}},
{"fw_ld4_topics_b_0040","outpost_medic",2,"reg=rescue",{1,"Pulse is steady",2,"Breathing?",1,"Shallow, but there",2,"Keep his head up, I'll get the oxygen"}},
{"s10_medic_attorney_splint_023","outpost_medic",2,"reg=rescue,civilian|day=5,300|mood=funny",{1,"Hold his arm still, I'm splinting it with the phone book",2,"Which section?",1,"Attorneys, thickest part of the book",2,"First time a lawyer ever held anybody together"}},
{"s10_medic_pickle_bucket_024","outpost_medic",3,"reg=civilian,family|tmp=fresh|day=3,120|mood=funny",{1,"Book says elevate the limb above the heart",2,"His whole leg?",1,"Prop it on the pickle bucket",3,"It says heart, it doesn't say pickle bucket",1,"The bucket's higher than his heart, I measured with a spoon"}},
{"s10_medic_on_two_025","outpost_medic",2,"reg=military,swat,law|tmp=seasoned,veteran|mood=funny",{1,"Shoulder goes back in on three - ready?",2,"Ready",1,"One - two",2,"AAH! You said three!",1,"Everybody tightens up on three - it's in, wiggle your fingers and stop cussing my mother"}},
{"s10_medic_chicken_coop_sleep_026","outpost_medic",2,"reg=rescue|role=rescue_medical,rescue_clergy|day=10,300|hour=4,9|mood=warm",{1,"I knew a woman who couldn't sleep for four nights. Sat up at every sound",2,"Did somebody try giving her allergy pills?",1,"Somebody suggested it. Being tired doesn't make every pill a sleeping pill",2,"I wish they'd asked what was scaring her before deciding they knew the answer"}},
{"s10_medic_pressure_pad_027","outpost_medic",3,"reg=law|day=3,300|mood=funny",{1,"Maxi pad, right on the hole, and push hard",2,"Are you serious right now?",1,"Best pressure dressing in the county, every cruiser in Knox should've had a box in the trunk",3,"Sheriff would never have signed that requisition",1,"Sheriff never bled on the Riverside road either - push"}},
{"s10_medic_glitter_cast_028","outpost_medic",2,"reg=rescue,family,civilian|day=10,300|mood=warm",{1,"Plaster's setting, came out of the craft store in {town}",2,"Is that glitter in her cast?",1,"Only plaster left was in the kids' art kits, she picked the purple one",2,"Best-looking broken arm in Kentucky"}},
{"s10_medic_counted_by_fives_029","outpost_medic",2,"reg=civilian,worker|tmp=fresh,seasoned|day=10,300|mood=funny",{1,"Everybody in camp calls me Doc now",2,"Weren't you the tech at the drugstore counter?",1,"Two years, I counted pills by fives with a little spatula",2,"Well, you've counted more pills than the rest of us put together - Doc"}},
{"s10_medic_steady_drunk_030","outpost_medic",3,"reg=raider,outlaw|tmp=predator,seasoned|mood=funny",{1,"Hold still - I'm sewing",2,"You're drunk",1,"I'm steady drunk, sober, I shake - you want the shaking?",3,"Pour more whiskey on it",2,"On it or in me?",1,"Both of you shut your mouths and let me sew"}},
{"s10_medic_orderly_thief_031","outpost_medic",2,"reg=prison|day=5,300|mood=funny",{1,"Who put you in charge of the medicine box?",2,"Nobody, I was orderly in the infirmary at La Grange",1,"And you stole out of it",2,"Every day for three years, that's why I know down to the pill what's in this one"}},
{"s10_medic_clean_sheet_door_cot_032","outpost_medic",2,"reg=rescue,civilian,military|tmp=seasoned,veteran|day=10,300|hour=4,11|mood=grim",{1,"Who put a clean sheet on the cot by the door?",2,"I did - this morning",1,"Nobody's on that cot",2,"Somebody will be, and I'd like them to get a clean sheet"}},
{"s10_medic_forehead_time_033","outpost_medic",2,"reg=elite|tmp=veteran|mood=calm",{1,"Tourniquet, high and tight",2,"On",1,"Time on it",2,"{time}, wrote it on his forehead in grease pencil",1,"Good, now he can't lose it either"}},
{"s10_medic_gerald_marker_034","outpost_medic",2,"reg=rescue,civilian,family|day=10,300|mood=funny",{1,"Gerald's back",2,"What is it today?",1,"Bug bite, he drew a circle around it in marker so we could watch it spread",2,"Did it spread?",1,"It went away, he's real upset about it"}},
{"s10_medic_lamp_smoke_035","outpost_medic",2,"reg=family|day=5,300|hour=18,23|mood=sad",{1,"Hold still, bug, one more little piece of glass",2,"Mama, you're crying",1,"It's the smoke off the lamp",2,"It's okay, Mama, it's just a little bit of blood"}},
{"s10_medic_back_page_column_036","outpost_medic",2,"reg=rescue|role=rescue_medical|tmp=seasoned|day=20,300|mood=grim",{1,"Logbook says {count} patients through this room since we opened it",2,"How many walked back out?",1,"That column's on the back page, I only look at it on Sundays"}},
{"s10_medic_named_aloe_037","outpost_medic",3,"reg=worker,civilian,family|day=10,300|mood=funny",{1,"He grabbed the generator muffler bare-handed",2,"There's an aloe plant in the Dotson kitchen window - bring the whole pot",3,"Mrs. Dotson named that plant - it's Gladys",2,"Then tell Gladys you're sorry on the way over"}},
{"s10_medic_tags_clink_038","outpost_medic",2,"reg=military|day=10,300|mood=grim",{1,"Doc keeps a bootlace full of dog tags hooked on his belt",2,"How many on there?",1,"Never counted, they clink when he walks - you always hear Doc before you see him"}},
{"s10_medic_great_neck_039","outpost_medic",2,"reg=civilian,worker,family|day=10,300|mood=funny",{1,"Only doctor in this camp is a chiropractor",2,"Better than nothing",1,"I came in with a fever, he cracked my neck",2,"Fever go down?",1,"No, my neck feels great, though"}},
{"s10_medic_mississippi_pulse_040","outpost_medic",2,"reg=rescue,civilian|day=5,300|mood=calm",{1,"Two fingers on his wrist - count fifteen seconds, then times it by four",2,"I don't have a watch",1,"Count Mississippis",2,"One Mississippi, two Mississippi.. nineteen beats",1,"Times four?",2,"Seventy-six - is that good?",1,"He's fine - you're fine - go scrub the pans"}},
{"s10_medic_model_glue_uncle_041","outpost_medic",2,"reg=gang,crime|mood=funny",{1,"Superglue, squeeze the cut shut and hold it",2,"That's for model airplanes",1,"Medics did it in Vietnam, my uncle said",2,"Your uncle said he flew helicopters too",1,"Hold it shut, uncle's story can wait"}},
{"s10_medic_piece_of_tennessee_042","outpost_medic",3,"reg=club|mood=funny",{1,"Road rash has to be scrubbed out, every bit of gravel",2,"With that brush?",1,"Unless you want gravel living in you the rest of your life - bite the glove",3,"I laid it down in eighty-one, still got a piece of Tennessee in my elbow",2,"Scrub it, I don't want a souvenir"}},
{"s10_medic_cherry_syrup_043","outpost_medic",1,"reg=rescue,civilian,family|tmp=seasoned|day=10,300|mood=grim",{1,"Gauze, eleven pads, tape, a roll and a half",1,"Aspirin, a coffee can of loose ones, kids' fever syrup, cherry, half a bottle",1,"Half a bottle of cherry, somebody's gonna fight me over that half bottle"}},
{"s10_medic_greener_than_him_044","outpost_medic",2,"reg=civilian,family,worker|tmp=fresh|mood=funny",{1,"I think I'm gonna faint",2,"Not on the patient - floor, head between your knees",1,"He's looking at me",2,"He's looking at you 'cause you're greener than he is"}},
{"exp_prison_skyshape","outside_life",2,"reg=prison|st=neutral,careful|world=door,fence",{1,"Keep looking for the fence, look up, think it oughta be there",2,"I keep counting doors",1,"Yeah?",2,"Yeah, don't even know I'm doing it till somebody asks"}},
{"exp_prison_ownshirt","outside_life",2,"reg=prison|st=neutral,careful|world=door,building",{1,"Thought about clothes a lot inside - stupid, huh? Just picking a shirt",2,"Not stupid, I thought about a door I could shut",1,"Yeah, a bathroom door",2,"With a lock, and nobody banging on the bastard"}},
